            // Add the ReVa plugin
            tool.addPlugin(RevaPlugin.class.getName());

            // Get the plugin instance
            for (ghidra.framework.plugintool.Plugin p : tool.getManagedPlugins()) {
                if (p instanceof RevaPlugin) {
                    plugin = (RevaPlugin) p;
                    break;
