        var state = createState();
        runOnServer.run(session -> {
            var realmModel = session.realms().getRealm(state.realmId);
            for (var userId : state.allUsers()) {
                session.loginFailures().removeUserLoginFailure(realmModel, userId);
            }
        });
    }

